using ClosedXML.Excel;
using Microsoft.EntityFrameworkCore;
using QL_KhachSan.DangNhap;
using QL_KhachSan.Models;

namespace QL_KhachSan.TaiKhoan;

internal sealed class FormDanhSachTaiKhoan : Form
{
    private readonly DataGridView _grid = HotelUi.Grid(); private readonly TextBox _search = HotelUi.TextBox("Tìm tài khoản hoặc nhân viên..."); private List<AccountRow> _all = [];
    public FormDanhSachTaiKhoan()
    {
        Text="Danh sách tài khoản";BackColor=HotelUi.Background;var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=1,RowCount=3};root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.Controls.Add(HotelUi.Heading("Quản lý tài khoản và quyền"),0,0);
        var tools=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,WrapContents=true};_search.Width=280;var add=HotelUi.Button("Thêm mới",true);var export=HotelUi.Button("Xuất Excel");add.Click+=(_,_)=>AddAccount();export.Click+=(_,_)=>Export();_search.TextChanged+=(_,_)=>Filter();tools.Controls.AddRange([_search,add,export]);root.Controls.Add(tools,0,1);
        _grid.Columns.Add("TenTK","Tên tài khoản");_grid.Columns.Add("TenNV","Nhân viên");_grid.Columns.Add("MaNV","Mã NV");_grid.Columns.Add("CapDo","Cấp độ quyền");_grid.Columns.Add(new DataGridViewButtonColumn{Name="Sua",HeaderText="Sửa",Text="Sửa",UseColumnTextForButtonValue=true,FillWeight=13,MinimumWidth=65});_grid.Columns.Add(new DataGridViewButtonColumn{Name="Xoa",HeaderText="Xóa",Text="Xóa",UseColumnTextForButtonValue=true,FillWeight=13,MinimumWidth=65});_grid.CellContentClick+=GridClick;root.Controls.Add(_grid,0,2);Controls.Add(root);Load+=(_,_)=>LoadData();
    }
    private void LoadData(){try{using var db=new HotelManagementContext();_all=db.TaiKhoans.AsNoTracking().Where(x=>x.DaXoa!=true&&x.MaNvNavigation.DaXoa!=true).OrderByDescending(x=>x.CapDoQuyen).ThenBy(x=>x.TenTk).Select(x=>new AccountRow{TenTK=x.TenTk,TenNV=x.MaNvNavigation.TenNv,MaNV=x.MaNv,CapDo=x.CapDoQuyen}).ToList();Filter();}catch(Exception ex){MessageBox.Show("Lỗi tải danh sách tài khoản: "+ex.GetBaseException().Message,"Lỗi",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
    private void Filter(){var q=_search.Text.Trim();var rows=_all.Where(x=>q.Length==0||x.TenTK.Contains(q,StringComparison.OrdinalIgnoreCase)||x.TenNV.Contains(q,StringComparison.OrdinalIgnoreCase)||x.MaNV.Contains(q,StringComparison.OrdinalIgnoreCase)).ToList();_grid.Rows.Clear();foreach(var x in rows)_grid.Rows.Add(x.TenTK,x.TenNV,x.MaNV,x.Quyen);}
    private void GridClick(object? s,DataGridViewCellEventArgs e){if(e.RowIndex<0)return;var username=_grid.Rows[e.RowIndex].Cells["TenTK"].Value?.ToString();if(string.IsNullOrWhiteSpace(username))return;switch(_grid.Columns[e.ColumnIndex].Name){case "Sua":using(var f=new FormSuaTaiKhoan(username))if(f.ShowDialog(this)==DialogResult.OK)LoadData();break;case "Xoa":Delete(username);break;}}
    private void AddAccount(){using var f=new FormThemTaiKhoan();if(f.ShowDialog(this)==DialogResult.OK)LoadData();}
    private void Delete(string username){if(FormDangNhap.CapDoQuyen_DangNhap!=3){MessageBox.Show("Chỉ Admin cấp 3 được xóa tài khoản.","Không đủ quyền",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(username==FormDangNhap.MaNV_DangNhap||_all.FirstOrDefault(x=>x.TenTK==username)?.MaNV==FormDangNhap.MaNV_DangNhap){MessageBox.Show("Không thể xóa tài khoản đang đăng nhập.","Thông báo",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(MessageBox.Show($"Bạn có chắc muốn xóa tài khoản '{username}'?","Xác nhận",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;try{using var db=new HotelManagementContext();var x=db.TaiKhoans.FirstOrDefault(t=>t.TenTk==username&&t.DaXoa!=true);if(x is null){MessageBox.Show("Không tìm thấy tài khoản.");return;}x.DaXoa=true;db.SaveChanges();LoadData();}catch(Exception ex){MessageBox.Show("Lỗi xóa tài khoản: "+ex.GetBaseException().Message);}}
    private void Export(){if(_grid.Rows.Count==0){MessageBox.Show("Không có dữ liệu để xuất.");return;}using var save=new SaveFileDialog{Filter="Excel Workbook (*.xlsx)|*.xlsx",FileName="DanhSachTaiKhoan.xlsx"};if(save.ShowDialog(this)!=DialogResult.OK)return;try{using var wb=new XLWorkbook();var ws=wb.Worksheets.Add("Danh sách tài khoản");for(var c=0;c<4;c++){ws.Cell(1,c+1).Value=_grid.Columns[c].HeaderText;ws.Cell(1,c+1).Style.Font.Bold=true;}for(var r=0;r<_grid.Rows.Count;r++)for(var c=0;c<4;c++)ws.Cell(r+2,c+1).Value=_grid.Rows[r].Cells[c].Value?.ToString()??"";ws.Columns().AdjustToContents();wb.SaveAs(save.FileName);MessageBox.Show("Xuất dữ liệu thành công.");}catch(Exception ex){MessageBox.Show("Lỗi xuất Excel: "+ex.Message);}}
}
